const cycleCard = code => ALL_CARDS[code]
const haystack = code => {
  const card = cycleCard(code)
  return `${card?.name || ''}\n${card?.text || ''}\n${card?.backText || ''}`
}
const cardsFor = patterns => CYCLE_CODES.filter(code => patterns.some(pattern => pattern.test(haystack(code))))
const idsTouched = classification => [...new Set([...classification.reuse, ...classification.extend, ...classification.new])]

