export const KEY_MECHANISMS = Object.freeze(KEY_MECHANIST_DEFS.map(def => {
  const cards = cardsFor(def.patterns)
  const classification = Object.freeze({
    reuse: Object.freeze([...def.classification.reuse]),
    extend: Object.freeze([...def.classification.extend]),
    new: Object.freeze([...def.classification.new]),
  })
  return Object.freeze({
    id: def.id,
    title: def.title,
    type: Object.freeze(Array.isArray(def.type) ? [...def.type] : [def.type]),
    patterns: Object.freeze(def.patterns.map(pattern => pattern.source)),
    cards: Object.freeze(cards),
    classification,
    primitiveIds: Object.freeze(idsTouched(classification)),
    gaps: Object.freeze(def.gaps.map(gap => Object.freeze({ ...gap }))),
    interactionGaps: Object.freeze([...def.interactionGaps]),
    note: def.note,
    evidence: Object.freeze([
      'docs/edgeOfTheEarth/README.md#5',
      'audit/eote-scope.json#cards',
      'src/engine/effects.js',
      'src/engine/api-mechanics.js',
    ]),
  })
}))
